import { createClientFromRequest } from 'npm:@base44/sdk@0.8.52';
import { actorOwnsListing, resolvePropertyActor } from '../../shared/propertyActor.ts';
import { buildMarketingPackage } from '../../shared/propertyMarketing.ts';
import { livePromotionForListing, promotionEntitlement } from '../../shared/propertyPromotionEngine.ts';

// Marketing materials for one property page.
//
// Read-only and free to call: captions and graphic specifications are deterministic, built from the
// customer's approved listing content and the approved photographs. Nothing is generated by an AI
// model, nothing is written to the database, and downloading the same asset again costs nothing.

function rows(result: any): any[] {
  return Array.isArray(result) ? result : (result?.items || []);
}

Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);
    const body = await req.json().catch(() => ({}));
    const listingId = String(body.listingId || body.listing_id || "");
    if (!listingId) return Response.json({ ok: false, error: "listingId is required" }, { status: 400 });

    const actor = await resolvePropertyActor(base44, body);
    const listing = rows(await base44.asServiceRole.entities.PropertyListing.filter({ listing_id: listingId }))[0];
    if (!listing) return Response.json({ ok: false, error: "PROPERTY_NOT_FOUND" }, { status: 404 });
    if (!actorOwnsListing(listing, actor)) {
      return Response.json({ ok: false, error: "FORBIDDEN" }, { status: 403 });
    }

    const current = await livePromotionForListing(base44, listingId);
    const entitlement = promotionEntitlement(current);
    const tier = entitlement.active ? entitlement.tier : "free";
    const marketing = buildMarketingPackage(listing, tier);

    return Response.json({
      ok: true,
      entitlement,
      // Free pages always get their shareable links; paid tiers add graphics and captions.
      locked: !entitlement.active,
      locked_message: entitlement.active
        ? ""
        : "Branded graphics and captions are part of Visibility Plus and Visibility Pro. Your shareable property link is below.",
      marketing,
    });
  } catch (error: any) {
    return Response.json({ ok: false, error: String(error?.message || error) }, { status: 500 });
  }
});